using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace McpServer;

[McpServerToolType]
public class WeatherTools
{
    private readonly HttpClient _httpClient;

    // Constructor injection — the MCP SDK resolves this from the DI container.
    public WeatherTools(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    [McpServerTool, Description("Get the current weather forecast for a US location by latitude/longitude.")]
    public async Task<string> GetForecast(
        [Description("Latitude of the location")] double latitude,
        [Description("Longitude of the location")] double longitude)
    {
        var url = $"https://api.weather.gov/points/{latitude},{longitude}";
        var pointResponse = await _httpClient.GetStringAsync(url);

        using var doc = JsonDocument.Parse(pointResponse);
        var forecastUrl = doc.RootElement
            .GetProperty("properties")
            .GetProperty("forecast")
            .GetString();

        if (forecastUrl is null)
            return "Could not resolve forecast URL for that location.";

        var forecastResponse = await _httpClient.GetStringAsync(forecastUrl);
        using var forecastDoc = JsonDocument.Parse(forecastResponse);

        var periods = forecastDoc.RootElement
            .GetProperty("properties")
            .GetProperty("periods");

        var result = new List<string>();
        foreach (var period in periods.EnumerateArray().Take(3))
        {
            var name = period.GetProperty("name").GetString();
            var detail = period.GetProperty("detailedForecast").GetString();
            result.Add($"**{name}**: {detail}");
        }

        return string.Join("\n\n", result);
    }

    [McpServerTool, Description("Get weather alerts for a US state (two-letter code, e.g. 'CA').")]
    public async Task<string> GetAlerts(
        [Description("Two-letter US state code")] string state)
    {
        var url = $"https://api.weather.gov/alerts/active?area={state}";
        var json = await _httpClient.GetStringAsync(url);
        using var doc = JsonDocument.Parse(json);

        var features = doc.RootElement.GetProperty("features");
        if (features.GetArrayLength() == 0)
            return $"No active alerts for {state}.";

        var alerts = new List<string>();
        foreach (var feature in features.EnumerateArray().Take(5))
        {
            var props = feature.GetProperty("properties");
            var headline = props.GetProperty("headline").GetString();
            alerts.Add($"• {headline}");
        }

        return string.Join("\n", alerts);
    }
}

